import { readFileSync } from 'node:fs';
import { join } from 'node:path';

export const VISUAL_DIR = join(__dirname, '..', 'visual');

/** Canonical routes, generated by e2e/visual/gen-routes.mjs from the data modules. */
export function loadRoutes(): string[] {
  const parsed = JSON.parse(readFileSync(join(VISUAL_DIR, 'routes.json'), 'utf8')) as { routes: string[] };
  return parsed.routes;
}

/** "/" becomes "home"; "/a/b" becomes "a__b". Safe as a folder name on every OS. */
export function routeSlug(route: string): string {
  if (route === '/') return 'home';
  return route.replace(/^\//, '').replace(/\//g, '__');
}
